// /frontend-react/src/components/HeaderBar.js

import React from 'react';

const HeaderBar = ({ title, onBackClick, isEasyMode }) => (
    <div style={{
        display: 'flex',
        alignItems: 'center',
        padding: '15px 20px',
        backgroundColor: '#f8f9fa', 
        borderBottom: '1px solid #e0e0e0',
        position: 'relative',
    }}>
        {onBackClick && (
            <button
                onClick={onBackClick}
                style={{
                    padding: '8px',
                    backgroundColor: 'transparent',
                    border: 'none',
                    borderRadius: '50%',
                    cursor: 'pointer',
                    fontSize: isEasyMode ? '30px' : '20px',
                    color: '#333',
                    marginRight: '15px',
                    transition: 'background-color 0.2s',
                    flexShrink: 0, // Prevent button from shrinking
                }}
                onMouseOver={e => e.currentTarget.style.backgroundColor = '#ddd'}
                onMouseOut={e => e.currentTarget.style.backgroundColor = 'transparent'}
            >
                <span role="img" aria-label="Back">◀️</span>
            </button>
        )}
        <h2 style={{
            fontSize: isEasyMode ? '36px' : '24px',
            margin: 0,
            color: '#333',
            overflow: 'hidden',
            textOverflow: 'ellipsis', // Handles long titles gracefully
            whiteSpace: 'nowrap'
        }}>
            {title}
        </h2>
    </div>
);

export default HeaderBar;
